per_case_results.actual_sql:
SELECT 
    ("Ariel Borysiuk"'s overall_rating - "Paulin Puel"'s overall_rating) / "Paulin Puel"'s overall_rating * 100 AS percentage_difference
FROM (
    SELECT "overall_rating" FROM "Player" WHERE "name" = 'Ariel Borysiuk'
    UNION ALL
    SELECT "overall_rating" FROM "Player" WHERE "name" = 'Paulin Puel'
) AS player_ratings
WHERE "overall_rating" IN (
    SELECT "overall_rating" FROM "Player" WHERE "name" = 'Ariel Borysiuk'
)
AND "overall_rating" IN (
    SELECT "overall_rating" FROM "Player" WHERE "name" = 'Paulin Puel'
);
